import React, { useState } from 'react';
import './components/Clientes/ClienteManagement.css'; // Importando o CSS corrigido
import ClienteList from './components/Clientes/ClienteList';
import CreateCliente from './components/Clientes/CreateCliente';
import ProjetoList from './components/Projetos/ProjetoList';
import CreateProjeto from './components/Projetos/CreateProjeto';
import AtividadeList from './components/Atividades/AtividadeList';
import CreateAtividade from './components/Atividades/CreateAtividade';

const App = () => {
  const [clientes, setClientes] = useState([]);
  const [selectedClienteId, setSelectedClienteId] = useState(null);
  const [selectedProjetoId, setSelectedProjetoId] = useState(null);
  const [searchQuery, setSearchQuery] = useState(''); // Para filtrar clientes

  // Função para lidar com o evento de busca
  const handleSearchChange = (e) => {
    setSearchQuery(e.target.value);
  };

  // Função de filtrar clientes
  const filteredClientes = clientes.filter(cliente =>
    cliente.nome.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="cliente-management">
      <h2>Gestão de Clientes</h2>

      {/* Campo de busca */}
      <div className="search-cliente-form">
        <input
          type="text"
          placeholder="Buscar por nome..."
          value={searchQuery}
          onChange={handleSearchChange}
        />
        <button onClick={() => {}}>Buscar</button>
      </div>

      {/* Formulário de criação de cliente */}
      <CreateCliente onCreate={setClientes} />

      {/* Lista de clientes */}
      <ClienteList
        clientes={filteredClientes}
        setSelectedClienteId={setSelectedClienteId}
      />

      {/* Renderizando detalhes do cliente, projetos, etc... */}
      {selectedClienteId && (
        <div>
          <ProjetoList
            clienteId={selectedClienteId}
            setSelectedProjetoId={setSelectedProjetoId}
          />
          <CreateProjeto clienteId={selectedClienteId} />

          {selectedProjetoId && (
            <div>
              <AtividadeList
                clienteId={selectedClienteId}
                projetoId={selectedProjetoId}
              />
              <CreateAtividade
                clienteId={selectedClienteId}
                projetoId={selectedProjetoId}
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default App;
